mapper.select:
SELECT u.user_id, u.login_id, u.user_name, u.department_id, d.department_code, d.department_name, u.vendor_id, v.vendor_name, u.role, u.active, u.created_at FROM app_user u LEFT JOIN department d ON d.department_id = u.department_id LEFT JOIN vendor v ON v.vendor_id = u.vendor_id
AND u.active = #{active}
ORDER BY u.user_id LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE app_user
SET user_name = #{form.userName}, department_id = #{form.departmentId}, vendor_id = #{form.vendorId},
	role = #{form.role}, active = #{form.active}

	, password = #{encodedPassword}

WHERE user_id = #{userId}
